<script setup>
import { ref,computed,watch,onMounted,onBeforeUnmount } from 'vue';
import { request } from '../../api/http';
import { apiUrl } from '../../api/config';
import { session } from '../../lib/session';
const props=defineProps({from:String,to:String,selection:Object});const emit=defineEmits(['close','open']);
const dialog=ref(null),kind=ref(props.selection.kind),query=ref(''),page=ref(0),rows=ref([]),more=ref(false),busy=ref(false),error=ref(''),audio=ref({}),audioBusy=ref({}),audioError=ref({});let controller,timer,generation=0;const recordings=new Map(),pending=new Set();
const title=computed(()=>kind.value==='updates'?'Lead Update History':kind.value==='convox'?'ConVox History':'CC History');
async function load(){const token=++generation;controller?.abort();controller=new AbortController();busy.value=true;error.value='';rows.value=[];audio.value={};audioError.value={};try{const response=await request('life_slimming.api.cc_report_history.history',{args:{kind:kind.value,from_date:props.from,to_date:props.to,agents:JSON.stringify(props.selection.agent?[props.selection.agent]:[]),start:page.value*30,limit:30,query:query.value},csrfToken:session.csrf_token,signal:controller.signal});if(token!==generation)return;rows.value=response.message.rows;more.value=!!response.message.has_more;}catch(e){if(token===generation&&e.name!=='AbortError')error.value=e.message;}finally{if(token===generation)busy.value=false;}}
watch([kind,page],load);
watch(query,()=>{clearTimeout(timer);timer=setTimeout(()=>{if(page.value!==0)page.value=0;else load();},300);},{flush:'sync'});
function tab(value){if(kind.value===value)return;clearTimeout(timer);query.value='';clearTimeout(timer);page.value=0;kind.value=value;}
async function play(row){const key=kind.value+':'+row.id,token=generation;if(audioBusy.value[key])return;audioBusy.value={...audioBusy.value,[key]:true};audioError.value={...audioError.value,[key]:''};const abort=new AbortController();pending.add(abort);try{let url=recordings.get(key);if(url===undefined){url=(await request('life_slimming.api.cc_report_history.recording',{args:{kind:kind.value,id:row.id},csrfToken:session.csrf_token,signal:abort.signal})).message.url;recordings.set(key,url);}if(token!==generation)return;if(!url){audioError.value={...audioError.value,[key]:'Recording unavailable.'};return;}audio.value={...audio.value,[key]:url.startsWith('/')?apiUrl(url):url};}catch(e){if(token===generation&&e.name!=='AbortError')audioError.value={...audioError.value,[key]:e.message};}finally{pending.delete(abort);audioBusy.value={...audioBusy.value,[key]:false};}}
onMounted(()=>{dialog.value.showModal();load();});onBeforeUnmount(()=>{generation++;controller?.abort();pending.forEach(c=>c.abort());clearTimeout(timer);});
</script>
<template><dialog ref="dialog" class="cc-history-dialog" @close="emit('close')"><header><div><h2>{{title}}</h2><small>{{selection.agent||'Selected agents'}} · {{from}} → {{to}}</small></div><button @click="dialog.close()">Close history</button></header><nav aria-label="Call history channels"><button v-for="[value,label] in [['mobile','CC History'],['convox','ConVox History'],['updates','Lead Updates']]" :key="value" :aria-pressed="kind===value" @click="tab(value)">{{label}}</button></nav><label class="history-search">Search lead, agent, status or phone last four digits<input v-model="query" type="search" autocomplete="off"></label><p v-if="error" class="cc-error" role="alert">{{error}} <button @click="load">Retry</button></p><p v-if="busy" role="status">Loading history…</p><div class="history-table"><table><thead><tr><th>Updated / call time</th><th>Agent</th><th>Lead</th><template v-if="kind==='updates'"><th>Field changes</th></template><template v-else><th>Mobile</th><th>Direction</th><th>Status</th><th>Talk seconds</th><th>Disposition</th><th>Recording</th></template></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{row.at}}</td><td>{{row.agent_name}}</td><td><button v-if="row.lead" @click="emit('open',row.lead)">{{row.client||row.lead}}</button><span v-else>—</span></td><template v-if="kind==='updates'"><td><div v-for="(change,i) in row.changes" :key="i"><strong>{{change.field}}</strong><p>{{change.before||'—'}} → {{change.after||'—'}}</p></div><span v-if="!row.changes?.length">No reportable field changes in this version.</span></td></template><template v-else><td>{{row.phone||'—'}}</td><td>{{row.direction||'—'}}</td><td>{{row.status}}</td><td>{{row.duration}}</td><td>{{row.disposition||'—'}}</td><td><button :disabled="audioBusy[kind+':'+row.id]" @click="play(row)">{{audioBusy[kind+':'+row.id]?'Loading…':'▶ Play'}}</button><audio v-if="audio[kind+':'+row.id]" :src="audio[kind+':'+row.id]" controls preload="none" @error="audioError={...audioError,[kind+':'+row.id]:'Playback failed. Check the recording or your access.'}"></audio><small role="status">{{audioError[kind+':'+row.id]}}</small></td></template></tr><tr v-if="!busy&&!rows.length"><td colspan="9">No records found for these agents and dates.</td></tr></tbody></table></div><footer><span>Showing {{rows.length?page*30+1:0}}–{{page*30+rows.length}}</span><button :disabled="busy||page===0" @click="page--">Previous</button><button :disabled="busy||!more" @click="page++">Next</button></footer></dialog></template>
<style scoped>.cc-history-dialog{width:min(1250px,96vw);max-height:90vh;box-sizing:border-box;overflow:auto;border:1px solid #d5b66b;border-radius:14px;color:#174b30;padding:18px}.cc-history-dialog::backdrop{background:#122e2466}header,nav,footer{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:12px}header{justify-content:space-between}h2{margin:0 0 5px}.history-search{display:grid;gap:5px;margin:12px 0}.history-search input{max-width:500px;padding:9px;border:1px solid #c5d4c9;border-radius:8px}button{padding:7px 10px;border:1px solid #a8c8b4;border-radius:7px;background:#f1f6ef;color:#174b30;cursor:pointer}button[aria-pressed=true]{background:#175a37;color:white}button:disabled{opacity:.5}.history-table{overflow:auto;max-height:58vh}table{width:100%;border-collapse:collapse;font-size:12px}td,th{padding:9px;border-bottom:1px solid #e3dccb;text-align:left;vertical-align:top}th{background:#f7f1df;white-space:nowrap}td{min-width:90px}td p{white-space:pre-wrap;overflow-wrap:anywhere;max-width:400px}audio{display:block;max-width:260px;margin-top:8px}small{display:block}footer{margin:12px 0 0}@media(max-width:600px){.cc-history-dialog{padding:10px}}</style>
